declare(strict_types=1);require_once __DIR__.'/includes/init.php';require_login();if(!is_encargado()&&!is_docente()){unset($_SESSION['user']);flash('danger','Este perfil ya no está habilitado en el sistema.');redirect('login.php');}
$pageTitle='Panel principal';$p=db();$recent=[];$anuncios=[];$roomStates=[];$activity=[];$liveSessions=[];
if(is_encargado()){
 $turn=manager_turn_id();
 $q=$p->prepare("SELECT COUNT(DISTINCT u.id) FROM usuarios u JOIN usuario_turnos ut ON ut.usuario_id=u.id WHERE u.rol='docente' AND u.activo=1 AND u.eliminado_en IS NULL AND ut.turno_id=:t AND ut.activo=1 AND ut.eliminado_en IS NULL");$q->execute(['t'=>$turn]);$docCount=(int)$q->fetchColumn();
 $q=$p->prepare("SELECT COUNT(*) FROM tickets WHERE turno_id=:t AND estado IN('abierto','en_revision','en_proceso')");$q->execute(['t'=>$turn]);$tickCount=(int)$q->fetchColumn();
 $faultCount=(int)$p->query("SELECT COUNT(*) FROM equipos WHERE activo=1 AND eliminado_en IS NULL AND estado IN('con_falla','mantenimiento')")->fetchColumn();
 $liveCount=(int)$p->query("SELECT COUNT(*) FROM sesiones_sala WHERE checkout_en IS NULL")->fetchColumn();
 $stats=['docentes'=>$docCount,'salas'=>(int)$p->query("SELECT COUNT(*) FROM salas WHERE activa=1 AND eliminado_en IS NULL")->fetchColumn(),'equipos'=>(int)$p->query("SELECT COUNT(*) FROM equipos WHERE activo=1 AND eliminado_en IS NULL")->fetchColumn(),'tickets'=>$tickCount,'fallas'=>$faultCount,'en_uso'=>$liveCount];
 $q=$p->prepare("SELECT t.id,t.tipo_problema,t.urgencia,t.estado,t.creado_en,CONCAT(u.nombre,' ',u.apellido) docente,COALESCE(e.codigo_inventario,'Sin equipo') equipo FROM tickets t JOIN usuarios u ON u.id=t.docente_id LEFT JOIN equipos e ON e.id=t.equipo_id WHERE t.turno_id=:t ORDER BY t.creado_en DESC LIMIT 6");$q->execute(['t'=>$turn]);$recent=$q->fetchAll();
 $rooms=$p->query("SELECT id,nombre,ubicacion FROM salas WHERE activa=1 AND eliminado_en IS NULL ORDER BY nombre")->fetchAll();foreach($rooms as $r){$r['status']=room_status_info((int)$r['id']);$roomStates[]=$r;}
 $q=$p->query("SELECT ss.id,ss.checkin_en,s.id sala_id,s.nombre sala,CONCAT(u.nombre,' ',u.apellido) docente FROM sesiones_sala ss JOIN salas s ON s.id=ss.sala_id JOIN usuarios u ON u.id=ss.docente_id WHERE ss.checkout_en IS NULL ORDER BY ss.checkin_en DESC LIMIT 6");$liveSessions=$q->fetchAll();
 $q=$p->prepare("SELECT l.accion,l.entidad,l.entidad_id,l.detalle,l.creado_en,COALESCE(CONCAT(u.nombre,' ',u.apellido),'Sistema') usuario FROM log_actividad l LEFT JOIN usuarios u ON u.id=l.usuario_id WHERE l.usuario_id IS NULL OR l.usuario_id IN (SELECT usuario_id FROM usuario_turnos WHERE turno_id=:t AND eliminado_en IS NULL) ORDER BY l.creado_en DESC LIMIT 8");$q->execute(['t'=>$turn]);$activity=$q->fetchAll();
}else{
 $uid=(int)current_user()['id'];$s=$p->prepare("SELECT COUNT(*) FROM horarios_docentes WHERE docente_id=:u AND anio_lectivo=YEAR(CURDATE()) AND dia_semana BETWEEN 1 AND 5 AND activo=1 AND eliminado_en IS NULL");$s->execute(['u'=>$uid]);$horarios=(int)$s->fetchColumn();$s=$p->prepare('SELECT COUNT(*) FROM tickets WHERE docente_id=:u');$s->execute(['u'=>$uid]);$ticks=(int)$s->fetchColumn();$s=$p->prepare('SELECT COUNT(*) FROM sesiones_sala WHERE docente_id=:u AND checkout_en IS NULL');$s->execute(['u'=>$uid]);$ses=(int)$s->fetchColumn();$stats=['horarios'=>$horarios,'tickets'=>$ticks,'sesiones'=>$ses];$s=$p->prepare("SELECT t.id,t.tipo_problema,t.urgencia,t.estado,t.creado_en,COALESCE(e.codigo_inventario,'Sin equipo') equipo FROM tickets t LEFT JOIN equipos e ON e.id=t.equipo_id WHERE t.docente_id=:u ORDER BY t.creado_en DESC LIMIT 6");$s->execute(['u'=>$uid]);$recent=$s->fetchAll();
 $s=$p->prepare("SELECT DISTINCT a.titulo,a.contenido,a.creado_en,tr.nombre turno FROM anuncios a JOIN turnos tr ON tr.id=a.turno_id JOIN usuario_turnos ut ON ut.turno_id=a.turno_id WHERE ut.usuario_id=:u AND ut.activo=1 AND ut.eliminado_en IS NULL AND a.activo=1 AND(a.fecha_inicio IS NULL OR a.fecha_inicio<=CURDATE()) AND(a.fecha_fin IS NULL OR a.fecha_fin>=CURDATE()) ORDER BY a.creado_en DESC");$s->execute(['u'=>$uid]);$anuncios=$s->fetchAll();
 $q=$p->prepare("SELECT DISTINCT s.id,s.nombre,s.ubicacion FROM salas s JOIN asignaciones_salas a ON a.sala_id=s.id WHERE a.docente_id=:d AND a.anio_lectivo=YEAR(CURDATE()) AND a.activa=1 AND s.activa=1 AND s.eliminado_en IS NULL ORDER BY s.nombre");$q->execute(['d'=>$uid]);$rooms=$q->fetchAll();foreach($rooms as $r){$r['status']=room_status_info((int)$r['id']);$roomStates[]=$r;}
}
require __DIR__.'/includes/header.php';$todayLabel=date('d/m/Y');?>
