 <article class="card"><div class="card-header"><h2>Uso en tiempo real</h2><span class="card-header-note">Sesiones abiertas</span></div><div class="card-body"><?php if(!$liveSessions):?><div class="empty-state">No hay salas ocupadas en este momento.</div><?php else:?><ul class="activity-list"><?php foreach($liveSessions as $ss):?><li><div><strong><?=e($ss['sala'])?></strong><span><?=e($ss['docente'])?></span></div><small>Desde <?=e(date('H:i',strtotime($ss['checkin_en'])))?></small></li><?php endforeach;?></ul><?php endif;?></div></article>
</section>

