 <article class="card"><div class="card-header"><h2>Actividad reciente</h2><span class="card-header-note">Últimos movimientos</span></div><div class="card-body"><?php if(!$activity):?><div class="empty-state">Todavía no hay actividad registrada.</div><?php else:?><ul class="activity-list"><?php foreach($activity as $a):?><li><div><strong><?=e($a['accion'])?></strong><span><?=e($a['usuario'])?><?=$a['detalle']?' · '.e($a['detalle']):''?></span></div><small><?=e(format_datetime($a['creado_en']))?></small></li><?php endforeach;?></ul><?php endif;?></div></article>
 <article class="card"><div class="card-header"><h2>Indicadores técnicos</h2></div><div class="card-body indicator-grid"><div><span>Equipos registrados</span><strong><?=$stats['equipos']?></strong></div><div><span>Con falla / mantenimiento</span><strong><?=$stats['fallas']?></strong></div><div><span>Tickets abiertos</span><strong><?=$stats['tickets']?></strong></div><div><span>Turno actual</span><strong class="indicator-text"><?=e(manager_turn_name())?></strong></div></div></article>
</section>
